// === Tab: mySketch ===
let pg;

let interactive = true;

let blobs = [];

function preload(){
	loadmyshader();
}

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	background(0);
	pg = createGraphics(width, height);
	pg.noStroke();

	for(let i=0; i<96; i++){
		blobs.push(new Blob());
	}
}

function draw() {
	let t = millis()/1000;

	pg.background("#fff");

	for(let b of blobs){
		if(!b.move(t)){
			b.init_pos();
		}
		b.render();
	}

	//image(pg, -width/2, -height/2);
	shader(theShader);
	theShader.setUniform("u_resolution", [width, height]);
	theShader.setUniform("u_time", t);
	theShader.setUniform("u_tex", pg);
	quad(-1, -1, 1, -1, 1, 1, -1, 1);
}

function keyPressed() {
  interactive = !interactive;
}

class Blob{
	constructor(){
		this.seed = random(99999);
		this.v = createVector(0, 0);
		this.init_pos();
		this.s = random(0.05, 0.15)*width;
		this.c = random()<0.1?"#f00":"#000";
		this.speed = width*random(0.004, 0.01);
	}

	init_pos(){
		let dir = random()>0.5;
		this.v = createVector(dir?-width*0.3:random(-0.1, 1.1)*width, dir?random(-0.1, 1.1)*height:-height*0.3);
	}

	move(t){
		this.v.add(createVector(noise(t, this.seed), noise(t, 500, this.seed)).mult(this.speed));
		if(interactive){
			let away = createVector(this.v.x-(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), this.v.y-(height-(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))) );
			this.v.add(away.setMag(this.speed*0.1/Math.pow(away.mag()/dist(0, 0, width, height), 0.5) ));
		}
		let relbord = p5.Vector.sub(this.v, createVector(width, height));
		if(relbord.x>this.s||relbord.y>this.s){
			return false;
		}
		else{
			return true;
		}
	}

	render(){
		pg.fill(this.c);
		pg.circle(this.v.x, this.v.y, this.s);
	}
}

// === Tab: Shader ===
let theShader;
function loadmyshader(){
	theShader = createShader(vert, frag);
}

const vert = `
	attribute vec3 aPosition;
	attribute vec2 aTexCoord;

	void main() {
		vec4 positionVec4 = vec4(aPosition, 1.0);
		positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

		gl_Position = positionVec4;
	}
`;

const frag = `
#ifdef GL_ES
precision mediump float;
#endif
//I learnt ray marching from Art of Code Youtube channel, go check him out!

#define MAX_STEPS 40
#define MAX_DIST 40.
#define SURF_DIST .01
//I didn't optimize this

uniform vec2 u_resolution;
uniform float u_time;
uniform sampler2D u_tex;

//https://iquilezles.org/articles/distfunctions
float sdBox( vec3 p, vec3 pos, vec3 b )
{
  vec3 q = abs(p-pos) - b;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}

//SPONGE
float GetDist(vec3 p){
    //the main cube
    float d = sdBox(p, vec3(0.), vec3(0.5));

    return d;
}

float RayMarch(vec3 ro, vec3 rd){
    float dO = 0.;

    for(int i=0; i<MAX_STEPS; i++){
        vec3 p = ro + rd*dO;
        float dS = GetDist(p);
        dO += dS;
        if(dO > MAX_DIST || dS < SURF_DIST) break;
    }

    return dO;
}

vec3 GetNormal(vec3 p){
    float d = GetDist(p);
    vec2 e = vec2(.01, 0.);

    vec3 n = d-vec3(
        GetDist(p-e.xyy),
        GetDist(p-e.yxy),
        GetDist(p-e.yyx)
    );

    return normalize(n);
}

float GetLight(vec3 p){
    vec3 lightPos = vec3(2., 10., 6.);

    vec3 l = normalize(lightPos-p);

    vec3 n = GetNormal(p);

    float dif = clamp(dot(n, l), 0., 1.);
    float d = RayMarch(p+n*SURF_DIST*2., l);
    if(d<length(lightPos-p)) dif*=0.1;

    return dif;
}

vec2 distort(vec3 seed, float time){
		return vec2(sin(time*seed.x)+seed.y*cos(seed.z), cos(dot(seed.yz, seed.zx)+sin(time+seed.y)));
}

float addUp(vec3 v){
    return v.x+v.y+v.z;
}

void main()
{
    vec2 uv = gl_FragCoord.xy/u_resolution;
    uv -= 1.;
    uv.x *= u_resolution.x/u_resolution.y;
		vec2 tex_uv = gl_FragCoord.xy/u_resolution;
		tex_uv *= .5;

    vec3 ro = vec3(1.);
    ro.xz = vec2(cos(u_time), sin(u_time))*5.;
    ro.y = sin(20.+u_time/2.)*5.;

    vec3 lookat = vec3(0.);

    vec3 f = normalize(lookat-ro);
    vec3 r = normalize(cross(vec3(0., 1., 0.), f));
    vec3 u = cross(f, r);

    vec3 i = uv.x*r + uv.y*u;

    vec3 rd = normalize(i-ro);

    float d = RayMarch(ro, rd);

    vec3 p = ro + rd*d;

    vec3 nor = GetNormal(p);
    if(d>MAX_DIST){
        nor = vec3(0.);
    }

    vec3 id = vec3(addUp(nor*vec3(1.,1.,-1.))>0.?1.:0.,
                    addUp(nor*vec3(1.,-1.,1.))>0.?1.:0.,
                    addUp(nor*vec3(-1.,1.,1.))>0.?1.:0.);
  	vec3 col = mix(texture2D(u_tex, tex_uv+distort(id, u_time)*0.1).rgb, texture2D(u_tex, tex_uv).rgb, smoothstep(MAX_DIST-1., MAX_DIST, d));
   gl_FragColor = vec4(col, 1.);
}
`;

